import React, {useState, useEffect} from 'react';
import Loading from "../components/UI/Loading/Loading"
import Emote from "../components/UI/Emote/Emote"
import EmoteWithUsername from "../components/UI/Emote/EmoteWithUsername"
import useTitle from '../hooks/useTitle'
import NavbarDashboard from "../components/UI/NavbarDashboard/NavbarDashboard"
import api from "../services/api"
import classnames from 'classnames';
import {useNavigate, Link} from 'react-router-dom'

const Emotes = () => {
	useTitle('BetterWASD | Эмоции')
	const navigate = useNavigate()

	const [isLoading, setIsLoading] = useState(true);
	const [data, setData] = useState({channelEmotes: [], sharedEmotes: []})
	const [show, setShow] = useState(false)
	const [error, setError] = useState(null)
	const [url, setURL] = useState('')
	
	const [createEmote, setCreateEmote] = useState({})

	useEffect(() => {
    const fetchData = async () => {
			try {
				setIsLoading(true)
				const {data: jdata} = await api.emote.getDashboardEmotes()
				setData(jdata)
			} catch (e) {
				console.log(e)
			} finally {
				setIsLoading(false)
			}
    };

    fetchData();
	}, [])

	const inputChange = (e) => {
		setURL(e.target.value.trim())
		setError(null)
		setCreateEmote(null)
	}

	const onSubmit = async () => {
		try {
			const {data} = await api.emote.postTvEmote({url: url})
			if (data.message && data._id && data.code) {
				navigate('/emotes/' + data._id);
			} else {
				setCreateEmote(data)
			}
		} catch (e) {
			setError(e.response.data.message)
		}
	}

	const onReCreate = async () => {
		try {
			const {data} = await api.emote.postTvEmote({url: url, recreate: true})
			if (data.message && data._id && data.code) {
				navigate('/emotes/' + data._id);
			} else {
				setCreateEmote(data)
			}
		} catch (e) {
			setError(e.response.data.message)
		}
	}

	return (
		<div>
		  <section className="question-section" style={{paddingBottom: '160px'}}>
			  <div className="items">
				<div className="item item_left">
					<NavbarDashboard defaultActiveKey="#/dashboard/emotes" />
				</div>
				<div className="item block item_right" style={{marginTop: '0px'}}>
					<div style={{display: 'flex', justifyContent: 'space-between'}}>
						<div className="item__title"> Эмоции </div>
						<div className="flat-btn ovg" style={{display: 'flex'}}>
							<button onClick={() => {setShow(true); setError(null); setCreateEmote(null)}} className={classnames('primary', 'medium', 'ovg')}> Создать эмоцию </button>
					  </div>
					</div>

					<div className="item__descr"> Любые смайлики, добавленные здесь, могут использоваться в чате вашего канала на WASD.TV как вами, так и вашими зрителями. </div>
					<div className="item__border"></div>

					{ isLoading ? <Loading /> : data.channelEmotes?.length || data.sharedEmotes?.length ? null : ('Вы еще на добавили эмоции') }

					{ data.channelEmotes?.length ? <div className="item__title"> Эмоции канала </div> : null}
					<div className="emotes">
						{ data.channelEmotes?.length ? data.channelEmotes.map((emote) => <Emote key={emote._id} emote={emote}/>) : null }
					</div>

					{ data.sharedEmotes?.length ? <div className="item__title" style={{'marginTop': '25px'}}> Общие эмоции </div> : null}
					<div className="emotes">
						{ data.sharedEmotes?.length ? data.sharedEmotes.map((emote) => <EmoteWithUsername key={emote._id} emote={emote}/>) : null }
					</div>
				</div>
			  </div>
		  </section>
			{show && <div className="ovg-modal-backdrop show"></div> }
			{show &&
	      <div className="ovg-modal-window show" onClick={(e) => {!isLoading && setShow(!(e.target.className.match('ovg-modal-window show') || e.target.className.match('hide')))}}>
			    <div className="modal-block modal-block_medium" style={{'width': '440px'}}>
	          <div className="modal-block__title">
	            <span> Создание эмоции из 7tv.app </span>
	          </div>

	          <div className="modal-block__content" style={{'padding': '0 24px'}}>
	            <div className="row">
	              <div className="col-36">
	                <label> На данный момент доступна возможность клонировать эмоцию из <a href="https://7tv.app/emotes" target="_blank" rel="noreferrer">7tv.app</a> </label>
	                <br></br>
									<br></br>
	                <label> Ссылка на эмоцию </label>
	              </div>
	              <div className="col-64">
	                <wasd-input>
	                  <div ovg="" className="wasd-input-wrapper" style={{flexDirection: 'column', alignItems: 'stretch'}}>
	                    <div ovg="" className="wasd-input">
	                      <input ovg="" placeholder="https://7tv.app/emotes/000000000000000000000000" type="text" className={classnames(isLoading && 'disabled' )} onChange={(e) => inputChange(e)}></input>
	                    </div>

											{createEmote?.message && createEmote._id && <div style={{display: 'flex', marginTop: '5px', fontSize: '12px', marginRight: '5px'}}>
												<span> {createEmote?.message} </span>

												<Link style={{marginLeft: '5px'}} to={`/emotes/${createEmote._id}`}> Просмотреть </Link>
											</div>}

											{createEmote?.message && createEmote._id && <div style={{display: 'flex', alignItems: 'center', marginTop: '5px', fontSize: '12px'}}>
												<span className=""> Создать новую эмоцю? </span>

												{/* <img width={32} height={32} alt="1" src={HOSTURL + "/cached/emote/"+createEmote?._id+"/1x"}/> */}
												
												{/* <img width={32} height={32} alt="2" src={createEmote?.newImg}/> */}

											</div>}

											{error && <span className="error" style={{marginTop: '5px'}}>{error}</span> }
	                  </div>
	                 </wasd-input>
	              </div>
	              {/* <div className="col-36" style={{display:'none'}}>
									<br></br>
	                <label style={{fontSize: '13px'}}> *Сгененируцте новый токен а после чего вставьте в поле выше* </label>
									<br></br>
									<br></br>
	              </div> */}
	            </div>
	          </div>

	          <div className="modal-block__footer">
	            <div className="flat-btn ovg" style={{'display': 'flex'}}>
	              <button className={classnames('medium', 'ovg', 'basic', 'hide', isLoading && 'disabled' )} style={{'marginRight': '5px'}}> отмена </button>
                {createEmote?.message && createEmote._id ? 
                  <button className={classnames('primary', 'medium', 'ovg', isLoading || url==='' || createEmote?.message && !createEmote._id && 'disabled' )} onClick={() => onReCreate()}> Создать новую </button>
                  :
                  <button className={classnames('primary', 'medium', 'ovg', isLoading || url==='' || createEmote?.message && createEmote._id && 'disabled' )} onClick={() => onSubmit()}> добавить </button>
                }

	            </div>
	          </div>
	        </div>
	      </div>
			}
		</div>
	);
};

export default Emotes;