import axios from "../axios";

const endpoint = {
    getEmote: () => axios.get("/v1/profile/current"),
    getDashboardEmotes: () => axios.get("/v1/emote/dashboard"),
    getUserEmotes: (id, limit, offset) => axios.get("/v1/emote/user/" + id + "?limit=" +limit + "&offset=" + offset),
    getEmoteById: (id) => axios.get("/v1/emote/"+id),
    getGlobalEmotes: () => axios.get("/v1/emote/global"),
    getSharedEmotes: (limit, offset, search) => axios.get(`/v1/emote/shared?limit=${limit}&offset=${offset}&query=${search}`),
    getTopEmotes: (limit, offset, search) => axios.get(`/v1/emote/top?limit=${limit}&offset=${offset}&query=${search}`),
    updateEmote: (id, data) =>  axios.put("/v1/emote/" + id, data),
    deleteEmote: (id, data) =>  axios.delete("/v1/emote/" + id, data),
    likeEmote: (id) => axios.put("/v1/emote/" + id + "/like"),
    unlikeEmote: (id) => axios.delete("/v1/emote/" + id + "/like"),
    postTvEmote: (data) => axios.post("/v1/emote/tv-emote", data)
}

export default endpoint;