import React, {useEffect, useState} from 'react';
import useTitle from '../hooks/useTitle'
import NavbarDashboard from "../components/UI/NavbarDashboard/NavbarDashboard"
import api from "../services/api"
import useAuth from "../hooks/useAuth"
import classnames from 'classnames';
import ColorPicker, { useColorPicker } from 'react-best-gradient-color-picker'

import TabGroup from "../components/UI/TabGroup/TabGroup"
import './user.css'

const Emotes = () => {
	useTitle('BetterWASD | Цвет имени')

	const userColors =  ["#7fba40", "#1c3fc8", "#a5276d", "#913ca7", "#4332b6", "#266bc5", "#5bc3c1", "#d87539", "#a9ad47", "#3ca13b", "#4db89a", "#6a4691", "#f5a623", "#e7719e", "#9fcbef", "#7b4b4b"];
	const auth = useAuth();
	const [carusel, setCarusel] = useState(auth.user?.paint?.length < 5 ? Number(auth.user?.paint) : 0)
	const [color, setColor] = useState(auth.user?.paint?.length < 5 ? 'rgba(255,255,255,1)' : auth.user?.paint)
	const [picker, setPicker] = useState( auth.user?.paint?.length > 5)

	const {setA} = useColorPicker(color, setColor)

	const onSave = async () => {
		const paint = getColor()
		await api.paint.setPaint({paint: paint})
		auth.setUser({...auth.user, paint: paint.toString()})
	}

	const onDelete = async () => {
		await api.paint.deletePaint()
		auth.setUser({...auth.user, paint: null})
	}

	useEffect(() => {
		setA('100')
	}, [setA])

	const getColor = () => {
		return picker ? color : carusel
	}

	const calculateCarusel = (e) => {
		if (e > 21) {
			setCarusel(0)
		} else if (e < 0) {
			setCarusel(21)
		} else {
			setCarusel(e)
		}
	}

	return (
		<section className="question-section paint" style={{paddingBottom: '160px'}}>
			<div className="items">
				<div className="item item_left">
					<NavbarDashboard defaultActiveKey="#/dashboard/paint" />
				</div>

				<div className="item block item_right" style={{marginTop: '0px'}}>
					<div className="item__title"> Цвет имени </div>
					<div className="item__descr"> Цвет доступен пользователям с BetterWASD. <br></br><p style={{fontSize: '14px', color: 'var(--wasd-color-text-fourth)'}}>Выдается на месяц, после чего цвет сбросится.</p> </div>
					<div className="item__border"></div>

					<TabGroup onChange={(e) => setPicker(!!e)} active={picker} tabs={[{title: 'Предустановленные цвета'}, {title: 'Цветовая палитра/градиент'}]} />

					<br></br>
					<br></br>

					<div style={{display: "flex", justifyContent: 'center', alignItems: 'center'}}>
						{
							!picker && <button onClick={() => calculateCarusel(carusel-1)} style={{width: '30px', height: '30px', marginRight: '5px', borderRadius: '20%', border: 'none', opacity: '.65'}}> <svg width="20" height="20" viewBox="0 0 24 24"><path d="M16.67 0l2.83 2.829-9.339 9.175 9.339 9.167-2.83 2.829-12.17-11.996z"></path></svg> </button>
						}
						<div style={{display: 'flex', flexDirection: 'column', alignItems: 'flex-start', fontSize: '14px', fontWeight: '400'}}>
							<span style={{padding: '5px', backgroundColor: '#141820', color: 'rgba(255, 255, 255, .88)'}}>
								<span style={{color: 'rgba(255, 255, 255, .64)', fontSize: '10px', heigth: '20px', marginRight: '8px'}}>10:00</span> { !picker ? 
									<span data-betterwasd-paint={carusel} style={{color: userColors[auth.user.user_id % (userColors.length - 1)]}}>{auth.user.user_login}</span> : color?.match('gradient') ? <span data-betterwasd-paint="" style={{backgroundImage: color}}>{auth.user.user_login}</span>
								:
									<span data-betterwasd-paint="" style={{color: color}}>{auth.user.user_login}</span>
								} <span style={{margin: '10px 4px'}}>Предпросмотр сообщения</span>
							</span>

							<span style={{padding: '5px', backgroundColor: '#f0f0f8', color: 'rgba(26, 32, 44, .88)'}}>
								<span style={{color: 'rgba(26, 32, 44, .64)', fontSize: '10px', heigth: '20px', marginRight: '8px'}}>10:00</span> { !picker ? 
									<span data-betterwasd-paint={carusel} style={{color: userColors[auth.user.user_id % (userColors.length - 1)]}}>{auth.user.user_login}</span> : color?.match('gradient') ? <span data-betterwasd-paint="" style={{backgroundImage: color}}>{auth.user.user_login}</span>
								:
									<span data-betterwasd-paint="" style={{color: color}}>{auth.user.user_login}</span>
								} <span style={{margin: '10px 4px'}}>Предпросмотр сообщения</span>
							</span>
						</div>
						{
							!picker && <button onClick={() => calculateCarusel(carusel+1)} style={{width: '30px', height: '30px', marginLeft: '5px', borderRadius: '20%', border: 'none', opacity: '.65'}}> <svg width="20" height="20" viewBox="0 0 24 24"><path d="M5 3l3.057-3 11.943 12-11.943 12-3.057-3 9-9z"></path></svg> </button>
						}
					</div>

					<div style={{padding: '10px 0', display: 'flex', justifyContent: 'center'}}>
						{
							picker && <div style={{width: '300px'}} className="color-picker">
								<ColorPicker hidePresets={true} hideEyeDrop={true} hideColorGuide={true} hideInputType={true} value={color} onChange={setColor} />
							</div>
						}
					</div>


					<div className="flat-btn ovg" style={{display: 'flex', paddingTop: '5px', flexDirection: 'column', alignItems: 'center'}}>
						{getColor()?.toString().length > 155 && <span className='' style={{marginBottom: '5px', color: 'rgba(var(--wasd-color-warning--rgb), .75)'}}> Вы используете большое количество цветов </span>}
						<button onClick={onSave} className={classnames('primary', 'medium', 'ovg', getColor()?.toString() === auth.user.paint?.toString() || getColor()?.toString().length > 155  ? 'disabled' : '')} style={{width: '300px'}}> Сохранить </button>
						<button onClick={onDelete} className={classnames('warning', 'medium', 'ovg', typeof auth.user?.paint !== 'string' ? 'disabled' : '' )} style={{marginTop: '5px', width: '300px'}}> Восстановить по умолчанию </button>
					</div>
					
				</div>
			</div>
		</section>
	);
};

export default Emotes;