import React, {useState, useEffect} from 'react';
import Loading from "../components/UI/Loading/LineLoading"
import Emote from "../components/UI/Emote/Emote"
import useTitle from '../hooks/useTitle'
import NavbarEmotes from "../components/UI/NavbarEmotes/NavbarEmotes"
import api from "../services/api"

import ReactPaginate from 'react-paginate'
import {useLocation, useNavigate, useSearchParams} from 'react-router-dom'

const Emotes = () => {
	useTitle('BetterWASD | Глобальные эмоции')

	const [isLoading, setIsLoading] = useState(true)
	const [error, setError] = useState(null)
	const [data, setData] = useState([])


	const navigate = useNavigate()
	const location = useLocation()
	const [searchParams] = useSearchParams();
	const limit = 30*2
	const [page, setPage] = useState(0)
  const [total, setTotal] = useState(null)

	// const {data = [], loading, error, response} = useFetch(HOSTURL + "/api/v1/emote/global?limit=" +limit + "&offset=" + page*limit, {}, [page]);
	// let total = response?.headers?.get('total')

	const pageChange = (e) => {
		setPage(e.selected)
		const to = { pathname: location.pathname, search: "?page="+(e.selected+1) };
		navigate(to, { replace: true });
	}

	useEffect(() => {
		const fetchData = async () => {
			try {
				setIsLoading(true)
				const {data: res, headers} = await api.emote.getGlobalEmotes()
        setTotal(headers.total)
				setData(res)
			} catch (e) {
				console.log(e)
				setError(e)
			} finally {
				setIsLoading(false)
				setError(null)
			}
		};
	
		fetchData();
	  document.querySelector('.wrapper')?.scrollTo({top: 0, left: 0})
	}, [page])

	return (
		<section className="question-section" style={{paddingBottom: '160px'}}>
			<div className="items">
				<div className="item item_left">
					<NavbarEmotes defaultActiveKey="#/emotes/global" />
				</div>
				<div className="item block item_right" style={{marginTop: '0px'}}>
					<div className="item__title"> Глобальные эмоции </div>
					<div className="item__descr"> Эмоции, которые можно использовать во всех чатах на WASD.TV с BetterWASD. </div>
					<div className="item__border"></div>
					<div className="emotes">
						{error && error.message}
						{isLoading && <Loading />}
						{data.length != 0 && data.map((emote) => <Emote key={emote._id} emote={emote}/>) }
					</div>
					{total > limit &&
						<ReactPaginate
							pageCount={Math.ceil(total/limit)}
							marginPagesDisplayed={2}
							pageRangeDisplayed={5}
							nextLabel="Следующая"
							previousLabel="Предыдущая"
							onPageChange={pageChange}
							containerClassName={'pagination justify-content-center'}
							pageClassName={'page-item'}
							pageLinkClassName={'page-link'}
							previousClassName={'page-item'}
							previousLinkClassName={'page-link'}
							nextClassName={'page-item'}
							nextLinkClassName={'page-link'}
							breakClassName={'page-item'}
							breakLinkClassName={'page-link'}
							activeClassName={'active'}
							disabledClassName={'disabled'}
							initialPage={searchParams.get('page') ? Number(searchParams.get('page'))-1 : 0}
						/>
					}
				</div>
			</div>
		</section>
	);
};

export default Emotes;