import React, {useState, useEffect} from 'react';
import {useParams} from 'react-router-dom';
import useTitle from '../hooks/useTitle'
import Loading from "../components/UI/Loading/Loading"
import Emote from "../components/UI/Emote/Emote"
import EmoteWithUsername from "../components/UI/Emote/EmoteWithUsername"
import api from "../services/api"


const Emotes = () => {
	const {id} = useParams();

	const [isLoading, setIsLoading] = useState(true)
	const [error, setError] = useState(null)
	const [data, setData] = useState([])

	useTitle(`BetterWASD | Профиль ${data?.user_login ? '| ' + data?.user_login : ''}`, [data])

	useEffect(() => {
		const fetchData = async () => {
			try {
				setIsLoading(true)
				const {data: res} = await api.emote.getUserEmotes(id, 0, 0)
				setData(res)
			} catch (e) {
				console.log(e)
				setError(e)
			} finally {
				setIsLoading(false)
			}
		};
	
		fetchData();
		// document.querySelector('.wrapper')?.scrollTo({top: 0, left: 0})
	}, [id])

	return (
		<section className="question-section" style={{paddingBottom: '160px'}}>
			{error && error.message && <div className="items">{error.message}</div>}
			{isLoading && <Loading />}
			{typeof data?.user_id != 'undefined' ? 
				<div className="items">
					<div className="item block item_right" style={{marginTop: '0px'}}>
						<div className="item__title"> Эмоции пользователя {data?.user_login} </div>
						<div className="item__descr"> Эмоции доступны на этом канале с BetterWASD. </div>
						<div className="item__border"></div>

						{data.channelEmotes.length != 0 &&
							<div>
								<div className="item__title"> Эмоции канала </div>
								<div className="emotes">
									{ data.channelEmotes.map((emote) => <Emote key={emote._id} emote={emote}/>) }
								</div>
							</div>
						}

						{data.sharedEmotes.length != 0 &&
							<div>
								<div className="item__title" style={{'marginTop': '25px'}}> Общие эмоции </div>
								<div className="emotes">
									{ data.sharedEmotes.map((emote) => <EmoteWithUsername key={emote._id} emote={emote}/>) }
								</div>
							</div>
						}
					</div>
				</div>
				:
				<div className="items">
					<div className="emotes">
						{data?.message}
					</div>
				</div>
			}
		</section>
	);
};

export default Emotes;