import React, {useState, useEffect} from 'react';
import Loading from "../components/UI/Loading/Loading"
import useTitle from '../hooks/useTitle'
import NavbarDashboard from "../components/UI/NavbarDashboard/NavbarDashboard"
import SubItemIcon from "../components/UI/SubItemIcon/SubItemIcon"
import api from "../services/api"
import useAuth from "../hooks/useAuth"
import classnames from 'classnames';
import './user.css'

const objectMap = (obj, fn) =>
  Object.fromEntries(
    Object.entries(obj).map(
      ([k, v], i) => [k, fn(v, k, i)]
    )
  )

const Emotes = () => {
	useTitle('BetterWASD | Значок подписчика')
	const auth = useAuth();

  const [isLoading, setIsLoading] = useState(true);
  const defBadges = {'1mon': 'https://static.wasd.tv/images/subscribers/1mon.png','3mon': 'https://static.wasd.tv/images/subscribers/3mon.png','6mon': 'https://static.wasd.tv/images/subscribers/6mon.png','9mon': 'https://static.wasd.tv/images/subscribers/9mon.png','12mon': 'https://static.wasd.tv/images/subscribers/12mon.png','18mon': 'https://static.wasd.tv/images/subscribers/18mon.png','24mon': 'https://static.wasd.tv/images/subscribers/24mon.png'}
  const nullBages = {'1mon': '', '3mon': '', '6mon': '', '9mon': '', '12mon': '', '18mon': '', '24mon': ''}
  const [subIcons, setSubIcons] = useState(nullBages)
  const [savedBadges, setSavedBadges] = useState(nullBages)
  const [isPartner, setIsPartner] = useState(false)




	useEffect(() => {
    const fetchData = async () => {
			try {
				setIsLoading(true)
				const {data: jdata} = await api.subBadge.getSubBadges()
        const mappedBadges = objectMap(jdata.badges, badge => badge === null ? '' : badge )
				setSubIcons(mappedBadges)
        setSavedBadges(mappedBadges)
        setIsPartner(jdata.is_partner)
			} catch (e) {
				console.log(e)
			} finally {
				setIsLoading(false)
			}
    };

    fetchData();
	}, [])

	const onSave = async () => {
		await api.subBadge.setSubBadges({badges: subIcons})
		setSavedBadges(subIcons)
	}

	const onDelete = async () => {
		await api.subBadge.deleteSubBadges()
		setSavedBadges(nullBages)
    setSubIcons(nullBages)
	}

  const [isLoadedImages, setIsLoadedImages] = useState({ '1mon': true, '3mon': true, '6mon': true, '9mon': true, '12mon': true, '18mon': true, '24mon': true })

	return (
		<section className="question-section paint" style={{paddingBottom: '160px'}}>
			<div className="items">
				<div className="item item_left">
					<NavbarDashboard defaultActiveKey="#/dashboard/sub-badges" />
				</div>

				<div className="item block item_right" style={{marginTop: '0px'}}>
					<div className="item__title"> Значок подписчика </div>
					<div className="item__descr"> Значок подписчика в чате доступен пользователям с BetterWASD. <br></br><p style={{fontSize: '14px', color: 'var(--wasd-color-text-fourth)'}}>Выдается на месяц, после чего иконка сбросится.</p> </div>
					<div className="item__border"></div>

          { isLoading ? <Loading /> : null }
          {
            isLoading ? null : isPartner
            ?
            <div>
              <div className="item__descr"> Рекомендуется размер изображения от 20 до 40px. </div>

              <div className="bonuses__icons">
                {Object.keys(subIcons).map((key, index) => <SubItemIcon index={index} item={key} subIcons={subIcons} defBadges={defBadges} setIsLoadedImages={setIsLoadedImages} isLoadedImages={isLoadedImages} setSubIcons={setSubIcons} key={index}></SubItemIcon>)}
              </div>
    
              <br></br>
    
              <div className="flat-btn ovg" style={{display: 'flex', paddingTop: '5px', flexDirection: 'column', alignItems: 'center'}}>
                <button onClick={onSave} className={classnames('primary', 'medium', 'ovg',
                auth.user && savedBadges &&
                !(subIcons['1mon'] === savedBadges['1mon'] &&
                subIcons['3mon'] === savedBadges['3mon'] &&
                subIcons['6mon'] === savedBadges['6mon'] &&
                subIcons['9mon'] === savedBadges['9mon'] &&
                subIcons['12mon'] === savedBadges['12mon'] &&
                subIcons['18mon'] === savedBadges['18mon'] &&
                subIcons['24mon'] === savedBadges['24mon']) &&
                isLoadedImages['1mon'] &&
                isLoadedImages['3mon'] &&
                isLoadedImages['6mon'] &&
                isLoadedImages['9mon'] &&
                isLoadedImages['12mon'] &&
                isLoadedImages['18mon'] &&
                isLoadedImages['24mon']
                ? '' : 'disabled')} style={{width: '300px'}}> Сохранить </button>
                <button onClick={onDelete} className={classnames('warning', 'medium', 'ovg',
                auth.user && savedBadges &&
                (savedBadges['1mon'] === '' &&
                savedBadges['3mon'] === '' &&
                savedBadges['6mon'] === '' &&
                savedBadges['9mon'] === '' &&
                savedBadges['12mon'] === '' &&
                savedBadges['18mon'] === '' &&
                savedBadges['24mon'] === '' ) ? 'disabled' : ''
                )} style={{marginTop: '5px', width: '300px'}}> Восстановить по умолчанию </button>
              </div>
            </div>
            : 'Эта функция доступна только для партнеров wasd.tv'
          }

					
				</div>
			</div>
		</section>
	);
};


export default Emotes;