import React, {useState, useEffect} from 'react';
import {useParams, useNavigate} from 'react-router-dom';
import Loading from "../components/UI/Loading/Loading"
import useTitle from '../hooks/useTitle'
import {decode} from '../lib/code-mnem'
import {Link} from 'react-router-dom';
import Moment from 'react-moment';
import User from "../components/UI/User/User"
import NotFound from "./NotFound"
import {HOSTURL} from "../index.js"
import api from "../services/api"
import useAuth from '../hooks/useAuth';

import classnames from 'classnames'

const Emotes = () => {
	const {id} = useParams();
	const auth = useAuth()

	const [isLoading, setIsLoading] = useState(true)
	const [error, setError] = useState(null)
	const [data, setData] = useState([])

	const [newData, setNewData] = useState(null)
	const [codeError, setCodeError] = useState('')

	const codeHandler = (e) => {
		setNewData({...newData, code: e.target.value})
		const re = /[^а-яА-Яa-zA-Z0-9]+/g
		if (re.test(String(e.target.value).toLowerCase())) {
			setCodeError('Ошибка валидации')
		} else {
			if (String(e.target.value).length === 0) {
				setCodeError('Код эмоции не может быть пустым')
			} else if (String(e.target.value).length < 3) {
				setCodeError('Количество сомволов не может быть меньше 3')
			} else if (String(e.target.value).length > 240) {
				setCodeError('Количество сомволов не может быть болоьще 240')
			} else {
				setCodeError('')
			}
		}
	}

	const navigate = useNavigate()

	useEffect(() => {
		const fetchData = async () => {
			try {
				setIsLoading(true)
				const {data: res} = await api.emote.getEmoteById(id)
				setData(res)
				setNewData(res)
			} catch (e) {
				console.log(e)
				setError(e)
			} finally {
				setIsLoading(false)
			}
		};
	
		fetchData();
		document.querySelector('.wrapper')?.scrollTo({top: 0, left: 0})
	}, [id])

	const encoded = decode(data?.code)
	useTitle(`BetterWASD | Emote ${data?.code ? '| ' + encoded : ''}`, [data])
	if (isLoading) return (<Loading />)
	if (error) return (<NotFound />)

	let column = [
		{
			marginRight: '10px',
			justifyContent: 'flex-start'
		}, {
			marginLeft: '10px'
		}, {
			display: 'flex',
			justifyContent: 'center'
		}, {
			width: '32vw'
		}, {
			display: 'flex',
			justifyContent: 'space-evenly',
			paddingTop: '5px'
		}, {
			maxWidth: '40%'
		}
	]

	const onUpdate = async () => {
		const {data: nData} = await api.emote.updateEmote(data._id, {code: newData.code, message: newData.message, sharing: newData.sharing})
		setData(nData)
		setNewData(nData)
	}

	const onDelete = async () => {
		const {data: nData} = await api.emote.deleteEmote(data._id)
		if (nData.ok) {
			setData(null)
			setNewData(null)
			navigate('/dashboard/emotes')
		}
	}

	const likeEmote = async () => {
		if (data.likes.is_liked) {
			const {data: nData} = await api.emote.unlikeEmote(data._id)
			if (nData) setData({...data, likes: {...nData}})
		} else {
			const {data: nData} = await api.emote.likeEmote(data._id)
			if (nData) setData({...data, likes: {...nData}})
		}
		console.log(data)
	}

	const is = (typeof data?.user?.user_id !== 'undefined' && data?.user?.user_id === auth.user?.user_id.toString()) || auth.user?.user_role === "ADMIN"
	const isOwner = typeof data?.user?.user_id !== 'undefined' && data?.user?.user_id === auth.user?.user_id

	if (!is) column = [{}, {}, {}, {width: '64vw'}, {}, {}]

	if (!data) return ('')

	return (
		<div style={column[2]}>
			<section className="d-flex-column" style={column[0]}>

				<div className="card block" style={column[3]}>
					<div className="card-header d-flex">
						<div style={{textTransform: 'none', 'wordBreak': 'break-all', 'marginRight': '50px'}}>{encoded}</div>
						{data.global !== false ?
							<div>Глобальная эмоция</div>
							:
							<div>загружено <Link to={'/users/' + data.user.user_id}>{data.user.user_login}</Link> <Moment date={data.createdAt} format="DD.MM.YYYY" /> </div>
						}
					</div>
					<div className="card-body" style={{'display': 'flex', 'alignItems': 'center', 'justifyContent': 'center'}}>
						<img style={column[5]} src={HOSTURL + "/cached/emote/" + data._id + "/1x"} alt="1x" />
						<img style={column[5]} src={HOSTURL + "/cached/emote/" + data._id + "/2x"} alt="2x" />
						<img style={column[5]} src={HOSTURL + "/cached/emote/" + data._id + "/3x"} alt="3x" />
					</div>
					{data.global === false && !isOwner && auth.user ?
						<div className="card-footer">
							<div className="flat-btn ovg" style={{display: 'flex'}}>
								{data.sharing ? <button onClick={likeEmote} className={classnames('medium', 'ovg', data.likes.is_liked ? 'warning' : 'primary')}> {data.likes.is_liked ? 'Удалить из канала' : 'Добавить на канал'} </button> : 'Доступно только в чате ' + data.user.user_login}
							</div>
						</div>
						:
						null
					}
				</div>

				{data?.likes?.total !== 0 ?
					<div className="card block" style={column[3]}>
						<div className="card-header d-flex">
							<div style={{textTransform: 'none'}}>Каналы ({data?.likes?.total})</div>
						</div>
						<div className="card-body">

							<div className="emotes">
								{ data && data.likes && data.likes.users ? data.likes.users.map((user) => <User key={user.user_id} user={user}/>) : <Loading /> }
							</div>

						</div>
					</div>
					:
					null
				}

			</section>

			{
				is ? 
				<section className="d-flex-column" style={column[1]}>

					<div className="card block" style={column[3]}>
						<div className="card-header d-flex">
							<div style={{textTransform: 'none'}}>Настройка</div>
						</div>
						<div className="card-body">
							<div>
								<span>Код эмоции</span>
								{codeError && <span className='error' style={{paddingLeft: '5px'}}>{codeError}</span>}
							</div>

							<wasd-input >
								<div ovg="" className="wasd-input-wrapper">
									<div ovg="" className={classnames("wasd-input", codeError && "warning")}>
										<input data-type="code" value={newData.code} onChange={e => codeHandler(e)} ovg="" placeholder="Код эмоции" type="text" />
									</div>
								</div>
							</wasd-input>

							<p style={{paddingTop: '5px', color: 'var(--wasd-color-text-third)'}}>Коды эмоций могут быть буквами и цифрами. Не менее 3 символов.</p>

							<div>Примечания об утверждении</div>

							<wasd-input>
								<div ovg="" className="wasd-input-wrapper">
									<div ovg="" className="wasd-input">
										<textarea value={newData.message} onChange={e => setNewData({...newData, message: e.target.value})} style={{height: '100px', maxHeight: '200px', minHeight: '40px'}} ovg="" placeholder="" type="text"></textarea>
									</div>
								</div>
							</wasd-input>

							<p style={{paddingTop: '5px', color: 'var(--wasd-color-text-third)'}}>Если ваша эмоция будет решена для проверки вручную (либо автоматически, либо кем-то, кто сообщил об этом), пожалуйста, объясните эту эмоцию и предоставьте обоснование для использования.</p>

							<div className="hover-pointer">
								<input id="sharing" type="checkbox" checked={newData.sharing} onChange={e => setNewData({...newData, sharing: e.target.checked})} />
								<label htmlFor="sharing" style={{marginLeft: '5px'}}>Совместное использование</label>
							</div>

							<p style={{paddingTop: '5px', color: 'var(--wasd-color-text-third)'}}>Включение общего доступа позволяет другим пользователям добавлять эту эмоцию в свой чат WASD.TV.</p>

						</div>
						<div className="card-footer flat-btn ovg" style={{display: 'flex'}}>
							<button onClick={onUpdate} disabled={codeError || !(data.code !== newData.code || data.sharing !== newData.sharing || data.message !== newData.message)} className="primary medium ovg"> Обновить эмоцию </button>
							<button onClick={onDelete} className="warning medium ovg" style={{marginLeft: '5px'}}> Удалить эмоцию </button>
						</div>
					</div>

				</section>
				:
				''
			}
		</div>
	);
};

export default Emotes;